import{_ as o,C as i,o as t,c as r,a3 as n,b as h,w as a,a as d,E as l,a4 as c}from"./chunks/framework.YvBpNZyo.js";const y=JSON.parse('{"title":"Accounts","description":"","frontmatter":{},"headers":[],"relativePath":"docs/accounts.md","filePath":"docs/accounts.md"}'),p={name:"docs/accounts.md"};function u(g,e,m,f,w,b){const s=i("Mermaid");return t(),r("div",null,[e[1]||(e[1]=n('<h1 id="accounts" tabindex="-1">Accounts <a class="header-anchor" href="#accounts" aria-label="Permalink to &quot;Accounts&quot;">​</a></h1><p>An account lets a guest keep their training across phones and use the website. Without one, everything stays on the phone, which is always the source of truth (<a href="./adr/0001-local-first-phone-is-the-source-of-truth">ADR 0001</a>). This page holds the rules (<a href="https://github.com/tkint/coach-poulpy/issues/25" target="_blank" rel="noreferrer">#25</a>). How sign-in works underneath is in <a href="./the-api">The API</a>, and how phones exchange data is in <a href="./sync">Sync</a>.</p><h2 id="signing-up" tabindex="-1">Signing up <a class="header-anchor" href="#signing-up" aria-label="Permalink to &quot;Signing up&quot;">​</a></h2><p>A guest signs up in the app with an email and a password, and agrees to the health-data consent. Apple and Google sign-in don&#39;t exist yet.</p><p>Nothing leaves the phone until the email is confirmed. Until the person opens the link in the email, the phone stays a guest and uploads nothing.</p><p>The link works on the phone or on any other device. If it opens elsewhere, the waiting phone notices and signs itself in. The confirmation sheet waits until a guided session or Live recording ends before it appears (<a href="https://github.com/tkint/coach-poulpy/issues/319" target="_blank" rel="noreferrer">#319</a>).</p><p>A person waiting for the link can ask for it again, or start over with another address. The old address stays unconfirmed.</p><h2 id="signing-in" tabindex="-1">Signing in <a class="header-anchor" href="#signing-in" aria-label="Permalink to &quot;Signing in&quot;">​</a></h2><p>Sign-in uses the email and password. After five failed tries in 15 minutes, sign-in pauses for a while.</p><p><strong>Coach Poulpy never reveals whether an email has an account.</strong> An unknown address and a wrong password get the same refusal. Signing up with an address that already has an account, or asking a reset for an address without one, looks exactly like a success.</p><p>A phone stays signed in until the person signs out, resets the password, deletes the account or someone revokes that sign-in. Then it becomes a guest again and keeps its data.</p><h2 id="forgotten-password" tabindex="-1">Forgotten password <a class="header-anchor" href="#forgotten-password" aria-label="Permalink to &quot;Forgotten password&quot;">​</a></h2><p>The person asks for a reset link by email and picks a new password. The link lasts one hour and works once. At most three links go out per hour.</p><p>A reset signs every device out, so anyone who knew the old password loses access.</p><h2 id="the-phone-and-the-account" tabindex="-1">The phone and the account <a class="header-anchor" href="#the-phone-and-the-account" aria-label="Permalink to &quot;The phone and the account&quot;">​</a></h2>',15)),(t(),h(c,null,{default:a(()=>[l(s,{id:"mermaid-45",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20guest(%5B%22Guest%20on%20phone%22%5D)%0A%20%20%20%20pending%5B%22Account%20created%3Cbr%2F%3Eemail%20not%20confirmed%3Cbr%2F%3Ephone%20remains%20a%20guest%22%5D%0A%20%20%20%20signedUp%5B%22Email%20confirmed%3Cbr%2F%3Ephone%20signs%20in%20and%20syncs%22%5D%0A%20%20%20%20merged%5B%22Existing%20account%3Cbr%2F%3Eguest%20data%20joins%20account%22%5D%0A%20%20%20%20cleared(%5B%22Signed%20out%3Cbr%2F%3Eempty%20guest%22%5D)%0A%0A%20%20%20%20guest%20--%3E%7Csign%20up%7C%20pending%0A%20%20%20%20pending%20--%3E%7Copen%20confirmation%20link%7C%20signedUp%0A%20%20%20%20guest%20--%3E%7Csign%20in%20to%20existing%20account%7C%20merged%0A%20%20%20%20signedUp%20--%3E%7Csign%20out%7C%20cleared%0A%20%20%20%20merged%20--%3E%7Csign%20out%7C%20cleared%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=n('<ul><li><strong>Signing in on a phone with guest data merges it into the account.</strong> Nothing is lost or overwritten.</li><li><strong>Signing out clears the phone</strong>, so the next person on a shared phone sees nothing. If some changes haven&#39;t been uploaded yet, the phone says so and lets the person wait or sign out anyway.</li></ul><h2 id="what-follows-the-account" tabindex="-1">What follows the account <a class="header-anchor" href="#what-follows-the-account" aria-label="Permalink to &quot;What follows the account&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Follows the account</th><th>Stays on each phone</th></tr></thead><tbody><tr><td>Workouts, plans, enrollments, sessions</td><td>Theme</td></tr><tr><td>Profile and body log</td><td>App icon</td></tr><tr><td>Units and language</td><td>Paired treadmills and other devices</td></tr></tbody></table><p>Phones sync while the app is open: when it opens, a few seconds after a change, and on pull to refresh. There is no background sync yet.</p><p>When two phones change the same thing, the rules are simple:</p><ul><li><strong>A workout edited on two phones is never lost.</strong> The second phone keeps its edit as a copy named after the phone, such as &quot;Leg day (Ana&#39;s iPhone)&quot;.</li><li><strong>An edit beats a delete.</strong> A workout deleted on one phone and edited on another comes back.</li><li><strong>Sessions are never merged.</strong> Only the phone that recorded a session changes it.</li><li><strong>For everything else</strong> (a planned day, a body measurement, a profile field) the latest change wins.</li></ul><h2 id="leaving" tabindex="-1">Leaving <a class="header-anchor" href="#leaving" aria-label="Permalink to &quot;Leaving&quot;">​</a></h2><ul><li><strong>Deleting the account is immediate</strong>, once the person types their password. All their data goes, every phone signs out and becomes a guest with its own copy, and backups age out within 30 days.</li><li><strong>Export</strong> gives all the account&#39;s data as JSON, and sessions as FIT files.</li></ul><h2 id="screens" tabindex="-1">Screens <a class="header-anchor" href="#screens" aria-label="Permalink to &quot;Screens&quot;">​</a></h2><p>The agreed screens are in the <a href="https://tkint.github.io/coach-poulpy/storybook/?path=/docs/mobile-screens-you-accounts--docs" target="_blank" rel="noreferrer">component workshop</a>, under Mobile → Screens → You → Accounts. They own the layout and the copy. This page owns the rules.</p>',10))])}const A=o(p,[["render",u]]);export{y as __pageData,A as default};
